import{_ as i,o as e,c as l,a2 as s}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"错题与弱项","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mistakes-and-weak-items.md","filePath":"guide/mistakes-and-weak-items.md","lastUpdated":1787830168000}'),t={name:"guide/mistakes-and-weak-items.md"};function n(r,a,o,d,p,h){return e(),l("div",null,[...a[0]||(a[0]=[s(`<h1 id="错题与弱项" tabindex="-1">错题与弱项 <a class="header-anchor" href="#错题与弱项" aria-label="Permalink to &quot;错题与弱项&quot;">​</a></h1><p>错题和弱项是两种不同的数据视图。错题描述发生过的错误事件；弱项描述由多次事件推导出的当前风险。</p><h2 id="错题记录" tabindex="-1">错题记录 <a class="header-anchor" href="#错题记录" aria-label="Permalink to &quot;错题记录&quot;">​</a></h2><p>一次错误可保存以下快照：</p><ul><li>Interaction 标识符。</li><li>题干与必要上下文。</li><li>正确答案。</li><li>用户答案。</li><li>来源课程、Lesson 或 Anki 卡片。</li><li>发生时间。</li></ul><p>快照用于重做和错误分析。它不替代原课程数据，也不应包含无关页面状态。</p><h2 id="弱项判定" tabindex="-1">弱项判定 <a class="header-anchor" href="#弱项判定" aria-label="Permalink to &quot;弱项判定&quot;">​</a></h2><p>弱项可由以下信号组合：</p><ul><li>近期 Again 或连续错误。</li><li>Stability 偏低。</li><li>到期后长期未复习。</li><li>同一语法点的多题错误。</li><li>课程提示使用层级持续升高。</li></ul><p>单次错误不等于长期弱项。诊断必须保留置信度，并在证据不足时明确返回低置信度。</p><h2 id="专项流程" tabindex="-1">专项流程 <a class="header-anchor" href="#专项流程" aria-label="Permalink to &quot;专项流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取错题 / SRS / 课程证据</span></span>
<span class="line"><span>  -&gt; 去重并按知识点归组</span></span>
<span class="line"><span>  -&gt; 选择有限数量的目标</span></span>
<span class="line"><span>  -&gt; 组装本地练习或 AI 练习</span></span>
<span class="line"><span>  -&gt; 执行并写入新证据</span></span>
<span class="line"><span>  -&gt; 更新弱项状态</span></span></code></pre></div><p>专项练习不能绕过正式评分事务。由 AI 生成的内容仍需符合题型和课程 schema。</p><h2 id="数据控制" tabindex="-1">数据控制 <a class="header-anchor" href="#数据控制" aria-label="Permalink to &quot;数据控制&quot;">​</a></h2><ul><li>删除错题记录不应删除课程资源。</li><li>清理可再生成缓存不应清除错题和 SRS。</li><li>关闭 AI 个性化后，不向 AI 请求附加旧会话或错题摘要。</li><li>脱敏报告不得包含原始题干、用户输入或 AI 对话。</li></ul><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ol><li>先处理到期复习。</li><li>再处理重复出现的错题组。</li><li>对单个高频失败项目检查内容质量和答案配置。</li><li>连续失败不一定是记忆问题，也可能是音频缺失、题干歧义或错误映射。</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/review-system">复习系统</a></li><li><a href="/docs/guide/ai-workflows">AI 工作流</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>`,19)])])}const m=i(t,[["render",n]]);export{u as __pageData,m as default};
